"""Build the investor experience into the server-only function bundle."""
from pathlib import Path
from html import escape
import json
import shutil


def build_investor_room(root):
    root = Path(root)
    market = json.loads((root / 'data/investor-market-research.json').read_text())
    research = json.loads((root / 'data/investor-program-research.json').read_text())
    catalog = json.loads((root / 'data/catalog.json').read_text())
    costs = json.loads((root / 'data/investor-cost-research.json').read_text())
    target = root / 'private/investor'
    target.mkdir(parents=True, exist_ok=True)
    e = lambda value: escape(str(value), quote=True)
    market_sources = {s['id']: s for s in market['sources']}
    cards = []
    for card in market['cards']:
        source = market_sources[card['sourceIds'][-1]]
        cards.append(f'''<article class="market-card"><p class="stat-value">{e(card['value'])}</p><h3>{e(card['label'])}</h3><p>{e(card['body'])}</p><div class="stat-meta">{e(card['period'])}<br>{e(card['population'])}</div><a class="source-link" href="{e(source['url'])}" target="_blank" rel="noopener noreferrer">Source &amp; methodology ↗</a></article>''')
    approved = sum(1 for t in catalog['tools'] if t.get('affiliateStatus') == 'approved' and t.get('affiliateUrl'))
    source_rows = []
    for sid in ['sba-2026-faq', 'chamber-2026-report', 'census-btos-overview']:
        s = market_sources[sid]
        source_rows.append(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["publisher"])} · {e(s["title"])} ↗</a></li>')
    payload = json.dumps({'research': research, 'costs': costs, 'asOf': market['asOf']}, ensure_ascii=False).replace('<', '\\u003c')
    page = TEMPLATE.replace('@@MARKET_CARDS@@', ''.join(cards)).replace('@@MARKET_SOURCES@@', ''.join(source_rows)).replace('@@DATA@@', payload).replace('@@APPROVED@@', str(approved)).replace('@@TOOLS@@', str(len(catalog['tools'])))
    (target / 'index.html').write_text(page, encoding='utf-8')
    for name in ['investor.css', 'investor.js', 'investor-costs.js', 'investor-model.js']:
        shutil.copyfile(root / 'site-assets' / name, target / name)
    return {'route': '/partners/investors/', 'assets': 5, 'access': 'server-session', 'indexed': False}


